import React, { useState, useEffect } from 'react'
import './GroupCard.scss'
import axios from 'axios';
import { Pencil, Trash2 } from 'lucide-react'

const GroupCard = () => {
    const [groups, setGroups] = useState([])

    const handleRemoveClick = async (groupName) => {
        try {
            await axios.delete(`http://localhost:8800/group/${groupName}`)
            getGroupDesc()
        } catch (error) {
            console.error(`Failed to delete group`)
        }
    }

    const getGroupDesc = async () => {
        try {
            const groupData = await axios.get('http://localhost:8800/groupdesc')
            setGroups(groupData.data)
        } catch (error) {
            console.error('Failed to fetch data', error)
        }
    }

    useEffect(() => {
        getGroupDesc()
    }, [])

    return (
        <div className='group-card-container'>
            {groups.map(group => (
                <div className='card-section' key={group.groupName}>
                    <h2 className='group-name'>{group.groupName}</h2>
                    <Trash2 className='remove-group-button' onClick={() => handleRemoveClick(group.groupName)} />
                    <p className='group-description'>{group.description}</p>
                    
                        <button className='edit-group-button'>
                            <Pencil />
                    </button>
                </div>
            ))}
        </div>
    )
}

export default GroupCard
